{"files":[{"content":"#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

const int MOD = 1000000007;

int main() {
    int n, m;
    cin >> n >> m;

    vector<vector<int>> blockedColumns(n);
    for (int c = 0; c < m; ++c) {
        int row, column;
        cin >> row >> column;
        blockedColumns[row].push_back(column);
    }

    for (auto& row : blockedColumns) {
        sort(row.begin(), row.end());
        row.erase(unique(row.begin(), row.end()), row.end());
    }

    vector<int> dp(n, 0);
    dp[0] = 1;

    for (int i = 0; i < n; ++i) {
        const vector<int>& row = blockedColumns[i];
        size_t blockedIndex = 0;

        if (blockedIndex < row.size() && row[blockedIndex] == 0) {
            dp[0] = 0;
            ++blockedIndex;
        }

        for (int j = 1; j < n; ++j) {
            if (blockedIndex < row.size() && row[blockedIndex] == j) {
                dp[j] = 0;
                ++blockedIndex;
            } else {
                int sum = dp[j] + dp[j - 1];
                if (sum >= MOD) {
                    sum -= MOD;
                }
                dp[j] = sum;
            }
        }
    }

    cout << dp[n - 1] << endl;
    return 0;
}
